const $=id=>document.getElementById(id);let rows=[];let connected=false;
function ping(){window.postMessage({source:'aiaa-group-finder-page',type:'PING'},'*')}
function render(items){rows=items||[];$('download').disabled=!rows.length;$('body').innerHTML=rows.length?rows.map((r,i)=>'<tr class="border-t"><td class="p-4 font-bold">#'+(i+1)+'</td><td class="p-4">'+escapeHtml(r.title||'Facebook 社團')+'</td><td class="p-4"><a class="break-all text-blue-700 underline" target="_blank" rel="noreferrer" href="'+escapeHtml(r.url)+'">'+escapeHtml(r.url)+'</a></td><td class="p-4">'+escapeHtml(r.keyword||'')+'</td></tr>').join(''):'<tr><td colspan="4" class="p-16 text-center text-slate-500">沒有取得結果</td></tr>'}
function escapeHtml(v){return String(v||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
window.addEventListener('message',e=>{if(e.source!==window||e.data?.source!=='aiaa-group-finder-extension')return;if(e.data.type==='EXTENSION_READY'){connected=true;$('connection').textContent='● Chrome 擴充功能已連線';$('connection').className='mt-5 inline-flex rounded-full bg-emerald-50 px-4 py-2 font-bold text-emerald-700';$('status').textContent='可以開始搜尋'}if(e.data.type==='SEARCH_STATUS')$('status').textContent=e.data.status;if(e.data.type==='SEARCH_BLOCKED'){render(e.data.results||[]);$('title').textContent='Google 真人驗證';$('status').textContent=e.data.status}if(e.data.type==='SEARCH_RESULTS'){render(e.data.results);$('title').textContent='真實 Google 搜尋結果';$('status').textContent='完成，共找到 '+rows.length+' 個社團'}});
$('search').addEventListener('click',()=>{const keywords=$('keyword').value.trim(),count=Math.max(1,Math.min(1000,Number($('count').value)||1));if(!keywords){alert('請輸入關鍵字');return}if(!connected){alert('Chrome 擴充功能尚未連線，請到 chrome://extensions 重新載入擴充功能，再重新整理本頁');ping();return}$('title').textContent='搜尋中…';$('status').textContent='正在交給擴充功能搜尋 Google';render([]);window.postMessage({source:'aiaa-group-finder-page',type:'START_SEARCH',keywords,count},'*')});
$('download').addEventListener('click',()=>{const esc=v=>'"'+String(v||'').replace(/"/g,'""')+'"';const data=[['排名','社團名稱','網址','搜尋關鍵字'],...rows.map((r,i)=>[i+1,r.title,r.url,r.keyword])];const blob=new Blob(['\ufeff'+data.map(x=>x.map(esc).join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='facebook-groups.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
ping();setTimeout(ping,1000);setTimeout(()=>{if(!connected){$('connection').textContent='● 擴充功能未連線';$('connection').className='mt-5 inline-flex rounded-full bg-red-50 px-4 py-2 font-bold text-red-700'}},2200);